import { afterEach, describe, expect, it, vi } from 'vitest';

vi.mock('../render/live-window', () => ({
  inTurn: <T>(request: () => Promise<T>): Promise<T> => request(),
}));

/*
 * Program capture's real reader loop, with only its browser media/DOM/port APIs stood in for. All frames contain
 * generated bytes. Nothing requests this computer's screen, camera or microphone. A stopped track's processor
 * can finish later: its deferred WebStream completion must not clear the capture that replaced it at a new size.
 */

class GeneratedFrame {
  readonly format = 'RGBA';
  readonly visibleRect: { x: number; y: number; width: number; height: number };
  private closed = false;

  constructor(
    readonly codedWidth: number,
    readonly codedHeight: number,
    private readonly byte: number,
  ) {
    this.visibleRect = { x: 0, y: 0, width: codedWidth, height: codedHeight };
  }

  allocationSize(): number {
    return this.codedWidth * this.codedHeight * 4;
  }

  copyTo(destination: ArrayBuffer): Promise<PlaneLayout[]> {
    if (this.closed) throw new Error('A closed generated frame cannot be copied.');
    new Uint8Array(destination).fill(this.byte);
    return Promise.resolve([]);
  }

  clone(): VideoFrame {
    if (this.closed) throw new Error('A closed generated frame cannot be cloned.');
    return new GeneratedFrame(this.codedWidth, this.codedHeight, this.byte).asVideoFrame();
  }

  close(): void {
    this.closed = true;
  }

  asVideoFrame(): VideoFrame {
    return this as unknown as VideoFrame;
  }
}

class GeneratedTrack extends EventTarget {
  readyState: MediaStreamTrackState = 'live';
  readonly readable: ReadableStream<VideoFrame>;
  private controller: ReadableStreamDefaultController<VideoFrame> | null = null;
  private readerFinished = false;
  processorStarted = false;
  // MediaStreamTrack.stop() does not synchronously finish every pending processor read or fire 'ended'.
  readonly stop = vi.fn(() => {
    this.readyState = 'ended';
  });

  constructor(
    readonly width: number,
    readonly height: number,
  ) {
    super();
    this.readable = new ReadableStream<VideoFrame>({
      start: (controller) => {
        this.controller = controller;
      },
    });
  }

  getSettings(): MediaTrackSettings {
    return { width: this.width, height: this.height, frameRate: 30 };
  }

  frame(byte: number): void {
    if (!this.controller || this.readerFinished) throw new Error('No generated frame reader.');
    this.controller.enqueue(new GeneratedFrame(this.width, this.height, byte).asVideoFrame());
  }

  finishReader(): void {
    if (this.readerFinished) return;
    this.readerFinished = true;
    this.controller?.close();
  }

  endNaturally(): void {
    this.readyState = 'ended';
    this.dispatchEvent(new Event('ended'));
    this.finishReader();
  }

  asTrack(): MediaStreamTrack {
    return this as unknown as MediaStreamTrack;
  }
}

class EncoderPort {
  readonly messages: unknown[] = [];
  readonly start = vi.fn();
  readonly close = vi.fn();

  postMessage(message: unknown): void {
    this.messages.push(message);
  }
}

function videoBytes(port: EncoderPort): number[][] {
  return port.messages.flatMap((message) => {
    if (
      typeof message !== 'object' ||
      message === null ||
      !('kind' in message) ||
      message.kind !== 'video' ||
      !('data' in message) ||
      !(message.data instanceof ArrayBuffer)
    )
      return [];
    return [Array.from(new Uint8Array(message.data))];
  });
}

let disposeCapture: (() => Promise<void>) | null = null;

afterEach(async () => {
  try {
    await disposeCapture?.();
  } finally {
    disposeCapture = null;
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
    vi.resetModules();
  }
});

async function platform(tracks: GeneratedTrack[]) {
  vi.resetModules();
  const lines: string[] = [];
  vi.spyOn(console, 'info').mockImplementation((message: unknown) => {
    if (typeof message === 'string') lines.push(message);
  });
  const page = new EventTarget();
  const body = { dataset: {} as Record<string, string> };
  interface Corner {
    id: string;
    dataset: Record<string, string>;
    style: { cssText: string; background: string };
    setAttribute: (name: string, value: string) => void;
  }
  const corners = new Map<string, Corner>();
  const document = {
    body: {
      ...body,
      appendChild: (corner: Corner) => {
        corners.set(corner.id, corner);
        return corner;
      },
    },
    getElementById: (id: string) => corners.get(id) ?? null,
    createElement: () => ({
      id: '',
      dataset: {},
      style: { cssText: '', background: '' },
      setAttribute: vi.fn(),
    }),
  };
  const queued = [...tracks];
  const getDisplayMedia = vi.fn(() => {
    const track = queued.shift();
    if (!track) return Promise.reject(new Error('Unexpected extra generated capture request.'));
    return Promise.resolve({ getVideoTracks: () => [track.asTrack()] } as unknown as MediaStream);
  });
  class Processor {
    readonly readable: ReadableStream<VideoFrame>;

    constructor({ track }: { track: MediaStreamTrack }) {
      const generated = tracks.find((candidate) => candidate.asTrack() === track);
      if (!generated) throw new Error('The processor received a non-generated track.');
      generated.processorStarted = true;
      this.readable = generated.readable;
    }
  }
  let interval = 1;
  vi.stubGlobal(
    'setInterval',
    vi.fn(() => interval++),
  );
  vi.stubGlobal('clearInterval', vi.fn());
  vi.stubGlobal('window', page);
  vi.stubGlobal('document', document);
  vi.stubGlobal('navigator', { mediaDevices: { getDisplayMedia } });
  vi.stubGlobal('MediaStreamTrackProcessor', Processor);
  const capture = await import('./capture');
  capture.startCapture(
    () => -100,
    () => null,
  );
  const deliver = (port: EncoderPort) => {
    const event = new Event('message');
    Object.defineProperties(event, {
      source: { value: page },
      data: { value: { drashtiStreamPort: 'encoder' } },
      ports: { value: [port] },
    });
    page.dispatchEvent(event);
  };
  const ended = (generation: number, frames: number) =>
    lines.includes(`[program] capture ${String(generation)} ended after ${String(frames)} frames`);
  disposeCapture = async () => {
    // Resolve platform requests before retiring them, then close only these generated readers.
    await expect
      .poll(() => tracks.filter((track) => track.processorStarted).length)
      .toBe(getDisplayMedia.mock.calls.length);
    capture.stopEncoder();
    capture.stopPreview();
    for (const track of tracks) track.finishReader();
    await expect
      .poll(
        () => lines.filter((line) => /^\[program\] capture \d+ ended after \d+ frames$/u.test(line)).length,
      )
      .toBe(tracks.filter((track) => track.processorStarted).length);
  };
  return { capture, deliver, getDisplayMedia, body, ended };
}

describe('Program capture after a reader ends', () => {
  it('asks for its picture again for a replacement encoder port and sends its new format and frame', async () => {
    const first = new GeneratedTrack(4, 2);
    const second = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([first, second, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const originalPort = new EncoderPort();
    p.deliver(originalPort);
    await expect.poll(() => first.processorStarted).toBe(true);
    first.frame(17);
    await expect.poll(() => videoBytes(originalPort)).toEqual([Array<number>(32).fill(17)]);

    first.endNaturally();
    await expect.poll(() => p.ended(1, 1)).toBe(true);
    const replacementPort = new EncoderPort();
    p.deliver(replacementPort);
    await expect.poll(() => p.getDisplayMedia.mock.calls.length).toBe(2);
    expect(p.getDisplayMedia).toHaveBeenNthCalledWith(2, {
      video: { width: 4, height: 2, frameRate: 30 },
      audio: false,
    });
    await expect.poll(() => second.processorStarted).toBe(true);
    second.frame(34);
    await expect.poll(() => videoBytes(replacementPort)).toEqual([Array<number>(32).fill(34)]);
    expect(replacementPort.messages[0]).toEqual({ kind: 'format', width: 4, height: 2, format: 'RGBA' });
    expect(originalPort.close).toHaveBeenCalledTimes(1);
    expect(p.body.dataset['capture']).toBe('on');
  });

  it('keeps the newer size, cached and following frames, and active marker when the previous reader finishes late', async () => {
    const first = new GeneratedTrack(4, 2);
    const second = new GeneratedTrack(6, 4);
    const unexpected = new GeneratedTrack(6, 4);
    const p = await platform([first, second, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const originalPort = new EncoderPort();
    p.deliver(originalPort);
    await expect.poll(() => first.processorStarted).toBe(true);
    first.frame(51);
    await expect.poll(() => videoBytes(originalPort)).toHaveLength(1);
    p.capture.setCaptureSize({ width: 6, height: 4 });
    await expect.poll(() => second.processorStarted).toBe(true);
    second.frame(68);
    await expect.poll(() => videoBytes(originalPort)).toHaveLength(2);
    expect(first.stop).toHaveBeenCalledTimes(1);

    // The old processor finishes only after the new capture has a valid cached frame.
    first.finishReader();
    await expect.poll(() => p.ended(1, 1)).toBe(true);
    const replacementPort = new EncoderPort();
    p.deliver(replacementPort);
    await expect.poll(() => videoBytes(replacementPort)).toEqual([Array<number>(96).fill(68)]);
    expect(replacementPort.messages[0]).toEqual({ kind: 'format', width: 6, height: 4, format: 'RGBA' });
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(2);
    expect(second.stop).not.toHaveBeenCalled();
    second.frame(85);
    await expect
      .poll(() => videoBytes(replacementPort))
      .toEqual([Array<number>(96).fill(68), Array<number>(96).fill(85)]);
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(2);
    // Separate current-generation metadata check: the old reader must not announce the new capture as off.
    expect(p.body.dataset['capture']).toBe('on');
  });

  it('marks the capture off after its last encoder stops and that reader finishes', async () => {
    const first = new GeneratedTrack(4, 2);
    const unexpected = new GeneratedTrack(4, 2);
    const p = await platform([first, unexpected]);
    p.capture.setCaptureSize({ width: 4, height: 2 });
    const port = new EncoderPort();
    p.deliver(port);
    await expect.poll(() => first.processorStarted).toBe(true);
    first.frame(102);
    await expect.poll(() => videoBytes(port)).toEqual([Array<number>(32).fill(102)]);

    // There is no preview port. Finish the stopped reader before checking its final state, as the old capture did.
    p.capture.stopEncoder();
    first.finishReader();
    await expect.poll(() => p.ended(1, 1)).toBe(true);
    expect(first.stop).toHaveBeenCalledTimes(1);
    expect(port.close).toHaveBeenCalledTimes(1);
    expect(p.getDisplayMedia).toHaveBeenCalledTimes(1);
    expect(p.body.dataset['capture']).toBe('off');
  });
});
